#!/usr/bin/env bash
set -Eeuo pipefail

# Two entry points:
#
# 1. Per-PR mode, for the legacy previews created before 30/08/2026 (Compose
#    project gesto-pr-N, volume gesto_pgdata_pr_N, no com.gesto.preview labels):
#      legacy-preview-cleanup.sh --pr=N --closed-prs=FILE
#      legacy-preview-cleanup.sh --pr=N --closed-prs=FILE --apply --expect-containers=3
#    Without --apply it only reports.  With --apply it removes ONE preview by
#    name after every check below passes; never compose down, never -f, never
#    prune.  FILE has one "N<TAB>CLOSED|MERGED" line per PR (generated by the
#    operator with gh); when an authenticated gh exists here it must agree.
#    The project volume is gesto_pgdata_pr_N or, for the oldest previews, the
#    old name gest-o_pgdata_pr_N with exactly the same N; any other gest-o_*
#    volume stops (production_volume).
#
# 2. Orphan preview volume (no container left):
#      legacy-preview-cleanup.sh --orphan-volume=NAME --closed-prs=FILE [--apply]
#    NAME must be gesto_pgdata_pr_N or gest-o_pgdata_pr_N, PR N closed or merged
#    in FILE (and in gh when authenticated), the volume must exist and no
#    container (running or not) may use it.  Simulation by default; --apply runs
#    `docker volume rm NAME` (never -f).
#
# 3. Manifest mode (inventory <manifest>): read-only verifier kept from PR #873;
#    "apply <manifest>" stays disabled.

# PR state: the file is mandatory; an authenticated gh must agree.  Uses the
# caller's pr, closed, repo, log, say and stop.
legacy_pr_state_check() {
  local line file_state='' matches=0 gh_state
  [[ -f "$closed" && -r "$closed" && ! -L "$closed" ]] || stop closed_prs_unreadable
  while IFS= read -r line || [[ -n "$line" ]]; do
    line=${line#$'\xef\xbb\xbf'}; line=${line%$'\r'}
    [[ -n "$line" ]] || continue
    [[ "$line" =~ ^([1-9][0-9]*)$'\t'(OPEN|CLOSED|MERGED)$ ]] || stop closed_prs_invalid_line
    if [[ "${BASH_REMATCH[1]}" == "$pr" ]]; then matches=$((matches + 1)); file_state=${BASH_REMATCH[2]}; fi
  done <"$closed"
  [[ "$matches" -eq 1 ]] || stop pr_state_missing_or_duplicated
  [[ "$file_state" == CLOSED || "$file_state" == MERGED ]] || stop pr_not_closed
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    gh_state=$(gh pr view "$pr" --repo "$repo" --json state -q .state 2>>"$log") || stop gh_query_failed
    [[ "$gh_state" == "$file_state" ]] || stop pr_state_sources_disagree
    say "PR_STATE=$file_state source=file+gh"
  else
    say "PR_STATE=$file_state source=file gh=unavailable"
  fi
}

legacy_pr_main() {
  local arg pr='' closed='' apply=no expect='' repo=${LEGACY_PREVIEW_REPOSITORY:-giancarlosmp-hub/Gest-o}
  local preview_root=${PREVIEW_ROOT:-/var/www/preview} nginx_dir=${NGINX_SITES_DIR:-/etc/nginx}
  local log_dir=${LEGACY_CLEANUP_LOG_DIR:-/var/log/gest-o/legacy-preview-cleanup}
  local evidence_dirs=("${DEPLOY_EVIDENCE_DIR:-/var/log/gest-o/deploy}" "${BUILD_EVIDENCE_DIR:-/var/log/gest-o/deploy-builds}"
    "${REBASELINE_EVIDENCE_DIR:-/var/log/gest-o/rebaseline}" "${RELEASE_ARTIFACT_ROOT:-/var/log/gest-o/oci-backups}")
  for arg in "$@"; do
    case "$arg" in
      --pr=*) pr=${arg#--pr=} ;;
      --closed-prs=*) closed=${arg#--closed-prs=} ;;
      --apply) apply=yes ;;
      --expect-containers=*) expect=${arg#--expect-containers=} ;;
      *) echo 'LEGACY_PREVIEW_RESULT=INVALID_ARGUMENT'; return 2 ;;
    esac
  done
  [[ "$pr" =~ ^[1-9][0-9]*$ ]] || { echo 'LEGACY_PREVIEW_RESULT=PR_REQUIRED'; return 2; }
  [[ -n "$closed" ]] || { echo 'LEGACY_PREVIEW_RESULT=CLOSED_PRS_REQUIRED'; return 2; }
  if [[ "$apply" == yes && ! "$expect" =~ ^[1-9][0-9]*$ ]]; then echo 'LEGACY_PREVIEW_RESULT=EXPECT_CONTAINERS_REQUIRED'; return 2; fi

  local project="gesto-pr-$pr" volume="gesto_pgdata_pr_$pr" old_volume="gest-o_pgdata_pr_$pr" network="gesto-pr-${pr}_default" stamp log
  stamp=$(date -u +%Y%m%dT%H%M%SZ)
  mkdir -p -- "$log_dir" || { echo 'LEGACY_PREVIEW_RESULT=LOG_DIR_UNAVAILABLE'; return 1; }
  chmod 700 -- "$log_dir" 2>/dev/null || :
  log="$log_dir/$stamp-pr-$pr.log"
  : >>"$log" || { echo 'LEGACY_PREVIEW_RESULT=LOG_DIR_UNAVAILABLE'; return 1; }
  chmod 600 -- "$log" || :
  say() { printf '%s\n' "$*"; printf '%s\n' "$*" >>"$log"; }
  stop() { say "LEGACY_PREVIEW_RESULT=STOPPED pr=$pr reason=$1 mutations=${mutations:-0}"; say "LEGACY_PREVIEW_LOG=$log"; exit 1; }
  local mutations=0
  say "LEGACY_PREVIEW_MODE=$([[ $apply == yes ]] && echo apply || echo simulation) pr=$pr project=$project"

  legacy_pr_state_check

  # --- Containers: exactly the legacy project, by label and by name. ---
  local names name by_label=() by_name=() containers=() facts image state cproject service labels mounts nets
  local -A api_web_images=()
  names=$(docker ps -a --no-trunc --format '{{.Names}}') || stop docker_unreadable
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    if [[ "$name" == "$project-"* ]]; then by_name+=("$name"); fi
  done <<<"$names"
  names=$(docker ps -a --no-trunc --filter "label=com.docker.compose.project=$project" --format '{{.Names}}') || stop docker_unreadable
  while IFS= read -r name; do if [[ -n "$name" ]]; then by_label+=("$name"); fi; done <<<"$names"
  [[ "$(printf '%s\n' "${by_name[@]}" | LC_ALL=C sort)" == "$(printf '%s\n' "${by_label[@]}" | LC_ALL=C sort)" ]] || stop container_set_diverged
  (( ${#by_name[@]} > 0 )) || stop no_containers
  local running=0 mtype mname
  local -A volumes_found=()
  for name in "${by_name[@]}"; do
    # New previews are gesto-pr-N-<run>-<attempt>-<service>-<n>; legacy ones are gesto-pr-N-<service>-<n>.
    [[ "$name" =~ ^gesto-pr-$pr-[a-z][a-z0-9_]*-[0-9]+$ ]] || stop container_name_not_legacy
    facts=$(docker container inspect -f '{{.Image}}|{{.State.Status}}|{{index .Config.Labels "com.docker.compose.project"}}|{{index .Config.Labels "com.docker.compose.service"}}' "$name") || stop docker_unreadable
    IFS='|' read -r image state cproject service <<<"$facts"
    [[ "$cproject" == "$project" ]] || stop container_project_diverged
    [[ "$image" =~ ^sha256:[0-9a-f]{64}$ ]] || stop container_image_id_unreadable
    labels=$(docker container inspect -f '{{range $k, $v := .Config.Labels}}{{$k}}{{"\n"}}{{end}}' "$name") || stop docker_unreadable
    if grep -q '^com\.gesto\.preview' <<<"$labels"; then stop container_has_new_preview_labels; fi
    mounts=$(docker container inspect -f '{{range .Mounts}}{{.Type}}|{{.Name}}{{"\n"}}{{end}}' "$name") || stop docker_unreadable
    while IFS='|' read -r mtype mname; do
      [[ -n "$mtype" ]] || continue
      [[ "$mtype" == volume ]] || stop unexpected_mount
      case "$mname" in
        "$volume"|"$old_volume") volumes_found[$mname]=1 ;;
        gest-o_pgdata*|gest-o_*) stop production_volume ;;
        *) stop unexpected_volume ;;
      esac
    done <<<"$mounts"
    nets=$(docker container inspect -f '{{range $k, $v := .NetworkSettings.Networks}}{{$k}}{{"\n"}}{{end}}' "$name") || stop docker_unreadable
    while IFS= read -r line; do
      [[ -z "$line" || "$line" == "$network" ]] || stop unexpected_network
    done <<<"$nets"
    if [[ "$state" == running ]]; then running=$((running + 1)); fi
    if [[ "$service" == api || "$service" == web ]]; then api_web_images[$image]=1; fi
    containers+=("$name")
    say "LEGACY_PREVIEW_PLAN object=container name=$name state=$state"
  done
  if [[ -n "$expect" && "$expect" != "${#containers[@]}" ]]; then stop expect_containers_mismatch; fi
  case "${#volumes_found[@]}" in
    1) volume=${!volumes_found[*]} ;;
    0) stop volume_not_found ;;
    *) stop volume_names_ambiguous ;;
  esac
  in_project() { local c; for c in "${containers[@]}"; do [[ "$c" == "$1" ]] && return 0; done; return 1; }

  # --- Volume: only gesto_pgdata_pr_N or gest-o_pgdata_pr_N, used by no container outside the project. ---
  names=$(docker ps -a --no-trunc --filter "volume=$volume" --format '{{.Names}}') || stop docker_unreadable
  while IFS= read -r name; do [[ -z "$name" ]] || in_project "$name" || stop volume_used_outside_project; done <<<"$names"
  say "LEGACY_PREVIEW_PLAN object=volume name=$volume"

  # --- Network: gesto-pr-N_default only, no foreign containers. ---
  local network_present=no
  names=$(docker network ls --format '{{.Name}}') || stop docker_unreadable
  while IFS= read -r name; do
    [[ "$name" == "$network" ]] && network_present=yes
    if [[ "$name" == "$project"_* && "$name" != "$network" ]]; then stop network_set_diverged; fi
  done <<<"$names"
  if [[ "$network_present" == yes ]]; then
    names=$(docker ps -a --no-trunc --filter "network=$network" --format '{{.Names}}') || stop docker_unreadable
    while IFS= read -r name; do [[ -z "$name" ]] || in_project "$name" || stop network_used_outside_project; done <<<"$names"
    say "LEGACY_PREVIEW_PLAN object=network name=$network"
  fi

  # --- Images: api/web of the project, no protected tag, no outside user, not in deploy evidence. ---
  local id tags tag dir evidence_present=() rc
  local -A image_tags=()
  for dir in "${evidence_dirs[@]}"; do
    if [[ -e "$dir" ]]; then [[ -d "$dir" ]] || stop evidence_unreadable; evidence_present+=("$dir"); fi
  done
  for id in "${!api_web_images[@]}"; do
    names=$(docker ps -a --no-trunc --filter "ancestor=$id" --format '{{.Names}}') || stop docker_unreadable
    while IFS= read -r name; do [[ -z "$name" ]] || in_project "$name" || stop image_used_outside_project; done <<<"$names"
    tags=$(docker image inspect -f '{{range .RepoTags}}{{.}}{{"\n"}}{{end}}' "$id") || stop docker_unreadable
    while IFS= read -r tag; do
      [[ -n "$tag" ]] || continue
      case "$tag" in
        gest-o*|*production*|*rollback*|*release*|*rebaseline*) stop image_protected_tag ;;
        "$project"-*|"$project"_*) ;;
        *) stop image_foreign_tag ;;
      esac
    done <<<"$tags"
    if (( ${#evidence_present[@]} > 0 )); then
      rc=0; grep -rlqF --exclude='*.tar' --exclude='*.tar.gz' -e "${id#sha256:}" -- "${evidence_present[@]}" 2>>"$log" || rc=$?
      case "$rc" in 0) stop image_in_deploy_evidence ;; 1) ;; *) stop evidence_unreadable ;; esac
    fi
    image_tags[$id]=$tags
    if [[ -n "$tags" ]]; then
      while IFS= read -r tag; do if [[ -n "$tag" ]]; then say "LEGACY_PREVIEW_PLAN object=image name=$tag"; fi; done <<<"$tags"
    else
      say "LEGACY_PREVIEW_PLAN object=image name=<untagged>"
    fi
  done

  # --- Preview directory: exact path, not a link, no new-style preview inside. ---
  local pdir="$preview_root/pr-$pr" pdir_present=no root_real
  if [[ -L "$pdir" ]]; then stop preview_dir_symlink; fi
  if [[ -e "$pdir" ]]; then
    [[ -d "$pdir" ]] || stop preview_dir_not_directory
    root_real=$(realpath -e -- "$preview_root") || stop preview_dir_unresolved
    [[ "$(realpath -e -- "$pdir")" == "$root_real/pr-$pr" ]] || stop preview_dir_path_diverged
    if [[ -n "$(find "$pdir" -mindepth 1 -maxdepth 1 -name "gesto-pr-$pr-*" -print -quit)" ]]; then stop preview_dir_has_new_preview; fi
    pdir_present=yes
    say "LEGACY_PREVIEW_PLAN object=preview_dir name=$pdir"
  fi

  # --- nginx: only crm-preview-pr-N; the shared crm-preview is never touched. ---
  local avail="$nginx_dir/sites-available/crm-preview-pr-$pr" enabled="$nginx_dir/sites-enabled/crm-preview-pr-$pr" site_present=no enabled_present=no
  if [[ -L "$avail" ]]; then stop nginx_site_unexpected; fi
  if [[ -e "$avail" ]]; then [[ -f "$avail" ]] || stop nginx_site_unexpected; site_present=yes; fi
  if [[ -L "$enabled" ]]; then
    [[ "$site_present" == yes && "$(readlink -- "$enabled")" == "$avail" ]] || stop nginx_site_unexpected
    enabled_present=yes
  elif [[ -e "$enabled" ]]; then stop nginx_site_unexpected
  fi
  if [[ "$site_present" == yes ]]; then
    say "LEGACY_PREVIEW_PLAN object=nginx_site name=crm-preview-pr-$pr enabled=$enabled_present"
  else
    say "LEGACY_PREVIEW_PLAN object=nginx_site nginx_site=shared_preserved"
  fi
  say "LEGACY_PREVIEW_PLAN object=nginx_shared_site name=crm-preview state=shared_preserved"

  local image_count=0 net_count=0 dir_count=0 site_count=0 t
  for id in "${!image_tags[@]}"; do image_count=$((image_count + 1)); done
  if [[ "$network_present" == yes ]]; then net_count=1; fi
  if [[ "$pdir_present" == yes ]]; then dir_count=1; fi
  if [[ "$site_present" == yes ]]; then site_count=1; fi
  say "LEGACY_PREVIEW_COUNTS containers=${#containers[@]} running=$running networks=$net_count volumes=1 images=$image_count preview_dirs=$dir_count nginx_sites=$site_count"

  if [[ "$apply" != yes ]]; then
    say "LEGACY_PREVIEW_RESULT=SIMULATED pr=$pr mutations=0"
    say "LEGACY_PREVIEW_LOG=$log"
    return 0
  fi

  # --- Apply: by name, in order; any failure stops. ---
  (( running == 0 )) || stop containers_running
  for name in "${containers[@]}"; do
    docker container rm "$name" >>"$log" 2>&1 || stop container_rm_failed
    mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=container name=$name"
  done
  if [[ "$network_present" == yes ]]; then
    docker network rm "$network" >>"$log" 2>&1 || stop network_rm_failed
    mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=network name=$network"
  fi
  docker volume rm "$volume" >>"$log" 2>&1 || stop volume_rm_failed
  mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=volume name=$volume"
  for id in "${!image_tags[@]}"; do
    while IFS= read -r t; do
      [[ -n "$t" ]] || continue
      docker image rm "$t" >>"$log" 2>&1 || stop image_rm_failed
      mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=image name=$t"
    done <<<"${image_tags[$id]}"
    if docker image inspect -f '{{.Id}}' "$id" >/dev/null 2>&1; then
      docker image rm "$id" >>"$log" 2>&1 || stop image_rm_failed
      mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=image name=<untagged>"
    fi
  done
  if [[ "$pdir_present" == yes ]]; then
    rm -r --one-file-system -- "$pdir" </dev/null >>"$log" 2>&1 || stop preview_dir_rm_failed
    mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=preview_dir name=$pdir"
  fi
  if [[ "$site_present" == yes ]]; then
    local backup="$log_dir/$stamp-pr-$pr.crm-preview-pr-$pr"
    cp -p -- "$avail" "$backup" || stop nginx_backup_failed
    if [[ "$enabled_present" == yes ]]; then rm -- "$enabled" || stop nginx_site_rm_failed; fi
    rm -- "$avail" || stop nginx_site_rm_failed
    if ! nginx -t >>"$log" 2>&1; then
      cp -p -- "$backup" "$avail" || stop nginx_test_failed_restore_failed
      if [[ "$enabled_present" == yes ]]; then ln -s -- "$avail" "$enabled" || stop nginx_test_failed_restore_failed; fi
      nginx -t >>"$log" 2>&1 || stop nginx_test_failed_restore_failed
      stop nginx_test_failed_site_restored
    fi
    systemctl reload nginx >>"$log" 2>&1 || stop nginx_reload_failed
    mutations=$((mutations + 1)); say "LEGACY_PREVIEW_REMOVED object=nginx_site name=crm-preview-pr-$pr"
  fi
  say "LEGACY_PREVIEW_RESULT=APPLIED pr=$pr mutations=$mutations"
  say "LEGACY_PREVIEW_LOG=$log"
}

legacy_orphan_volume_main() {
  local arg volume='' closed='' apply=no pr repo=${LEGACY_PREVIEW_REPOSITORY:-giancarlosmp-hub/Gest-o}
  local log_dir=${LEGACY_CLEANUP_LOG_DIR:-/var/log/gest-o/legacy-preview-cleanup} stamp log names name found=no
  for arg in "$@"; do
    case "$arg" in
      --orphan-volume=*) volume=${arg#--orphan-volume=} ;;
      --closed-prs=*) closed=${arg#--closed-prs=} ;;
      --apply) apply=yes ;;
      *) echo 'LEGACY_PREVIEW_RESULT=INVALID_ARGUMENT'; return 2 ;;
    esac
  done
  [[ "$volume" =~ ^(gesto|gest-o)_pgdata_pr_([1-9][0-9]*)$ ]] || { echo 'LEGACY_PREVIEW_RESULT=ORPHAN_VOLUME_NAME_INVALID'; return 2; }
  pr=${BASH_REMATCH[2]}
  [[ -n "$closed" ]] || { echo 'LEGACY_PREVIEW_RESULT=CLOSED_PRS_REQUIRED'; return 2; }

  stamp=$(date -u +%Y%m%dT%H%M%SZ)
  mkdir -p -- "$log_dir" || { echo 'LEGACY_PREVIEW_RESULT=LOG_DIR_UNAVAILABLE'; return 1; }
  chmod 700 -- "$log_dir" 2>/dev/null || :
  log="$log_dir/$stamp-orphan-volume-pr-$pr.log"
  : >>"$log" || { echo 'LEGACY_PREVIEW_RESULT=LOG_DIR_UNAVAILABLE'; return 1; }
  chmod 600 -- "$log" || :
  say() { printf '%s\n' "$*"; printf '%s\n' "$*" >>"$log"; }
  stop() { say "LEGACY_PREVIEW_RESULT=STOPPED pr=$pr reason=$1 mutations=${mutations:-0}"; say "LEGACY_PREVIEW_LOG=$log"; exit 1; }
  local mutations=0
  say "LEGACY_PREVIEW_MODE=$([[ $apply == yes ]] && echo apply || echo simulation) orphan_volume=$volume pr=$pr"

  legacy_pr_state_check

  names=$(docker volume ls --format '{{.Name}}') || stop docker_unreadable
  while IFS= read -r name; do if [[ "$name" == "$volume" ]]; then found=yes; fi; done <<<"$names"
  [[ "$found" == yes ]] || stop volume_not_found
  names=$(docker ps -a --no-trunc --filter "volume=$volume" --format '{{.Names}}') || stop docker_unreadable
  [[ -z "$names" ]] || stop volume_in_use
  say "LEGACY_PREVIEW_PLAN object=orphan_volume name=$volume containers=0"

  if [[ "$apply" != yes ]]; then
    say "LEGACY_PREVIEW_RESULT=SIMULATED pr=$pr mode=orphan_volume mutations=0"
    say "LEGACY_PREVIEW_LOG=$log"
    return 0
  fi
  docker volume rm "$volume" >>"$log" 2>&1 || stop volume_rm_failed
  mutations=1; say "LEGACY_PREVIEW_REMOVED object=orphan_volume name=$volume"
  say "LEGACY_PREVIEW_RESULT=APPLIED pr=$pr mode=orphan_volume mutations=$mutations"
  say "LEGACY_PREVIEW_LOG=$log"
}

if [[ "${1:-}" == --* ]]; then
  for arg in "$@"; do
    if [[ "$arg" == --orphan-volume=* ]]; then legacy_orphan_volume_main "$@"; exit $?; fi
  done
  legacy_pr_main "$@"
  exit $?
fi

# Manifest mode: read-only verifier for legacy Compose projects. The manifest
# does not prove PR/run identity, so its apply stays disabled; use --pr above.
mode=${1:-inventory}; manifest=${2:-}
[[ "$mode" == inventory || "$mode" == apply ]] || { echo 'LEGACY_PREVIEW_RESULT=INVALID_MODE'; exit 2; }
[[ -r "$manifest" ]] || { echo 'LEGACY_PREVIEW_RESULT=MANIFEST_REQUIRED'; exit 2; }
header=$'project\tpr\tcontainer_ids\tnetwork_ids'
[[ "$(head -n1 "$manifest")" == "$header" ]] || { echo 'LEGACY_PREVIEW_RESULT=INVALID_HEADER'; exit 2; }

rows=$(awk 'NR>1 && NF {n++} END {print n+0}' "$manifest")
if [[ "$mode" == apply ]]; then
  [[ "$rows" == 1 ]] || { echo 'LEGACY_PREVIEW_RESULT=APPLY_SINGLE_PROJECT_REQUIRED'; exit 1; }
  echo 'LEGACY_PREVIEW_RESULT=APPLY_DISABLED'
  echo 'PR_STATE=NOT_PROVEN reason=legacy_resources_have_no_independent_pr_run_ownership'
  exit 1
fi
(( rows > 0 )) || { echo 'LEGACY_PREVIEW_RESULT=EMPTY_MANIFEST'; exit 1; }

canonical_csv() {
  tr ',' '\n' | sed '/^$/d' | LC_ALL=C sort -u | paste -sd, -
}

while IFS=$'\t' read -r project pr container_csv network_csv extra; do
  [[ -z "${extra:-}" && "$project" =~ ^[a-zA-Z0-9][a-zA-Z0-9_.-]+$ && "$pr" =~ ^[0-9]+$ ]] || { echo 'LEGACY_PREVIEW_RESULT=INVALID_ROW'; exit 1; }
  [[ -n "$container_csv" && -n "$network_csv" ]] || { echo 'LEGACY_PREVIEW_RESULT=INSUFFICIENT_EVIDENCE'; exit 1; }
  expected_containers=$(printf '%s' "$container_csv" | canonical_csv)
  expected_networks=$(printf '%s' "$network_csv" | canonical_csv)
  [[ "$(printf '%s' "$container_csv" | tr ',' '\n' | sed '/^$/d' | wc -l)" == "$(printf '%s' "$expected_containers" | tr ',' '\n' | wc -l)" ]] || { echo 'LEGACY_PREVIEW_RESULT=DUPLICATE_RESOURCE'; exit 1; }
  [[ "$(printf '%s' "$network_csv" | tr ',' '\n' | sed '/^$/d' | wc -l)" == "$(printf '%s' "$expected_networks" | tr ',' '\n' | wc -l)" ]] || { echo 'LEGACY_PREVIEW_RESULT=DUPLICATE_RESOURCE'; exit 1; }

  actual_containers=$(docker ps -aq --no-trunc --filter "label=com.docker.compose.project=$project" | LC_ALL=C sort -u | paste -sd, -)
  actual_networks=$(docker network ls -q --no-trunc --filter "label=com.docker.compose.project=$project" | LC_ALL=C sort -u | paste -sd, -)
  [[ "$actual_containers" == "$expected_containers" && "$actual_networks" == "$expected_networks" ]] || { echo 'LEGACY_PREVIEW_RESULT=PROJECT_SET_DIVERGED'; exit 1; }

  IFS=, read -ra containers <<<"$expected_containers"; IFS=, read -ra networks <<<"$expected_networks"
  network_names=()
  for id in "${networks[@]}"; do
    [[ "$id" =~ ^[a-f0-9]{64}$ ]] || { echo 'LEGACY_PREVIEW_RESULT=FULL_ID_REQUIRED'; exit 1; }
    facts=$(docker network inspect -f '{{.Id}}{{"\t"}}{{.Name}}{{"\t"}}{{index .Labels "com.docker.compose.project"}}' "$id")
    IFS=$'\t' read -r observed_id network_name observed_project <<<"$facts"
    [[ "$observed_id" == "$id" && -n "$network_name" && "$observed_project" == "$project" ]] || { echo 'LEGACY_PREVIEW_RESULT=IDENTITY_DIVERGED'; exit 1; }
    network_names+=("$network_name")
  done
  expected_network_names=$(printf '%s\n' "${network_names[@]}" | LC_ALL=C sort -u | paste -sd, -)
  for id in "${containers[@]}"; do
    [[ "$id" =~ ^[a-f0-9]{64}$ ]] || { echo 'LEGACY_PREVIEW_RESULT=FULL_ID_REQUIRED'; exit 1; }
    facts=$(docker container inspect -f '{{.Id}}{{"\t"}}{{.Name}}{{"\t"}}{{index .Config.Labels "com.docker.compose.project"}}{{"\t"}}{{.State.Status}}' "$id")
    IFS=$'\t' read -r observed_id name observed_project state <<<"$facts"
    [[ "$observed_id" == "$id" && "$observed_project" == "$project" && "$name" == /* && -n "$state" ]] || { echo 'LEGACY_PREVIEW_RESULT=IDENTITY_DIVERGED'; exit 1; }
    case "${name#/}" in
      gest-o-production-api-1|gest-o-production-web-1|gest-o-db-clean-v2-20260717) echo 'LEGACY_PREVIEW_RESULT=PRODUCTION_CONTAINER_PROTECTED'; exit 1;;
    esac
    mounts=$(docker container inspect -f '{{range .Mounts}}{{if eq .Type "volume"}}{{.Name}}{{"\n"}}{{end}}{{end}}' "$id")
    if printf '%s\n' "$mounts" | grep -Fxq -e gest-o_pgdata -e gest-o_pgdata_clean_v2_20260717; then echo 'LEGACY_PREVIEW_RESULT=PROTECTED_VOLUME'; exit 1; fi
    attached=$(docker container inspect -f '{{range $name, $_ := .NetworkSettings.Networks}}{{$name}}{{"\n"}}{{end}}' "$id" | sed '/^$/d' | LC_ALL=C sort -u | paste -sd, -)
    [[ -n "$attached" && "$attached" == "$expected_network_names" ]] || { echo 'LEGACY_PREVIEW_RESULT=TOPOLOGY_DIVERGED'; exit 1; }
  done
  echo "LEGACY_PREVIEW_INVENTORY=PASS project=$project containers=${#containers[@]} networks=${#networks[@]}"
  echo "PR_STATE=NOT_PROVEN declared_pr=$pr"
done < <(tail -n +2 "$manifest")
echo 'LEGACY_PREVIEW_RESULT=PASS mode=inventory mutations=0'
